44	at::Tensor upsample_nearest(
45	    const at::Tensor &input,
46	    at::IntArrayRef output_size,
47	    bool exact_mode)
48	{
49	    // ---- Input validation ----
50	    TORCH_CHECK(input.ndimension() == 4,
51	                "upsample_nearest: expected 4D input (N,C,H,W), got ", input.ndimension());
52	    TORCH_CHECK(output_size.size() == 2,
53	                "upsample_nearest: output_size must have 2 elements, got ", output_size.size());
54	
55	    int64_t nBatch = input.size(0);
56	    int64_t cDim = input.size(1);
57	    int64_t inH = input.size(2);
58	    int64_t inW = input.size(3);
59	    int64_t outH = output_size[0];
60	    int64_t outW = output_size[1];
61	
62	    TORCH_CHECK(inH > 0 && inW > 0, "upsample_nearest: input spatial dims must be > 0");
63	    TORCH_CHECK(outH > 0 && outW > 0, "upsample_nearest: output spatial dims must be > 0");
64	
65	    // ---- Compute scale factors ----
66	    float scaleH = static_cast<float>(inH) / static_cast<float>(outH);
67	    float scaleW = static_cast<float>(inW) / static_cast<float>(outW);
68	
69	    // ---- Channel tile size with vector alignment ----
70	    // Minimum vector width: 32 bytes per operation
71	    int64_t elemSize = static_cast<int64_t>(input.element_size());
72	    int64_t vecWidth = 32 / elemSize;  // 8 for f32, 16 for f16/bf16
73	    int64_t paddedC = ((cDim + vecWidth - 1) / vecWidth) * vecWidth;
74	
75	    int64_t inSpatial = inH * inW;
76	    int64_t outSpatial = outH * outW;
77	    int64_t totalRows = nBatch * outSpatial;
78	
79	    int64_t inRows = nBatch * inSpatial;
80	    int64_t outRows = nBatch * outSpatial;
81	
82	    int64_t blockC;
83	    if (paddedC <= 256) {
84	        blockC = paddedC;
85	    } else {
86	        blockC = 128;
87	    }
88	
89	    // ---- Flatten inputs and pad to vector width ----
90	    auto inputNhwc = input.permute({0, 2, 3, 1}).contiguous();
91	    auto xFlat = inputNhwc.reshape({inRows, cDim}).contiguous();
92	
93	    // Create padded input: (inRows, paddedC), pad with zeros
94	    auto xPadded = at::zeros({inRows, paddedC}, input.options());
95	    xPadded.narrow(1, 0, cDim).copy_(xFlat);
96	
97	    // Output: allocate padded (outRows, paddedC)
98	    auto yPadded = at::zeros({outRows, paddedC}, input.options());
99	
100	    // ---- Build tiling struct on CPU ----
101	    auto tilingCpu = at::empty({static_cast<int64_t>(sizeof(UpsampleNearestTiling))},
102	                                at::device(at::kCPU).dtype(at::kByte));
103	    auto *tilingPtr = reinterpret_cast<UpsampleNearestTiling *>(tilingCpu.data_ptr());
104	    tilingPtr->N = static_cast<int32_t>(nBatch);
105	    tilingPtr->C = static_cast<int32_t>(cDim);
106	    tilingPtr->paddedC = static_cast<int32_t>(paddedC);
107	    tilingPtr->inH = static_cast<int32_t>(inH);
108	    tilingPtr->inW = static_cast<int32_t>(inW);
109	    tilingPtr->outH = static_cast<int32_t>(outH);
110	    tilingPtr->outW = static_cast<int32_t>(outW);
111	    tilingPtr->inSpatial = static_cast<int32_t>(inSpatial);
112	    tilingPtr->outSpatial = static_cast<int32_t>(outSpatial);
113	    tilingPtr->scaleH = scaleH;
114	    tilingPtr->scaleW = scaleW;
115	    tilingPtr->exactMode = exact_mode ? 1 : 0;
116	    tilingPtr->blockC = static_cast<int32_t>(blockC);
117	    tilingPtr->totalRows = static_cast<int32_t>(totalRows);
118	
119	    // Copy tiling to device
120	    auto tilingNpu = tilingCpu.to(at::kPrivateUse1);
121	
122	    // ---- Get core count and UB budget ----
123	    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
124	    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
125	    uint64_t ubSize;
126	    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
127	
128	    // Check UB budget: 2 io bufs (input + output) of blockC elements
129	    uint64_t requiredUB = static_cast<uint64_t>(blockC) * static_cast<uint64_t>(elemSize) * 2ULL;
130	    while (blockC > static_cast<int64_t>(vecWidth) && requiredUB > ubSize) {
131	        blockC = (blockC / 2 / vecWidth) * vecWidth;
132	        if (blockC < static_cast<int64_t>(vecWidth)) blockC = vecWidth;
133	        tilingPtr->blockC = static_cast<int32_t>(blockC);
134	        requiredUB = static_cast<uint64_t>(blockC) * static_cast<uint64_t>(elemSize) * 2ULL;
135	        tilingNpu = tilingCpu.to(at::kPrivateUse1);
136	    }
137	
138	    // ---- Set launch blocks ----
139	    int64_t blockDim = static_cast<int64_t>(coreNum);
140	    tilingPtr->launchBlocks = static_cast<int32_t>(blockDim);
141	    tilingNpu = tilingCpu.to(at::kPrivateUse1);
142	
143	    // ---- Launch kernel ----
144	    if (input.scalar_type() == at::kFloat) {
145	        EXEC_KERNEL_CMD(upsample_nearest_float, blockDim,
146	                        xPadded, yPadded, tilingNpu);
147	    } else if (input.scalar_type() == at::kHalf) {
148	        EXEC_KERNEL_CMD(upsample_nearest_half, blockDim,
149	                        xPadded, yPadded, tilingNpu);
150	    } else if (input.scalar_type() == at::kBFloat16) {
151	        EXEC_KERNEL_CMD(upsample_nearest_bf16, blockDim,
152	                        xPadded, yPadded, tilingNpu);
153	    } else {
154	        TORCH_CHECK(false, "upsample_nearest: unsupported dtype ", input.scalar_type());
155	    }
156	
157	    // Strip padding and convert back to NCHW layout
158	    auto yFlat = yPadded.narrow(1, 0, cDim).contiguous();
159	    auto yNhwc = yFlat.reshape({nBatch, outH, outW, cDim});
160	    auto output = yNhwc.permute({0, 3, 1, 2}).contiguous();
161	    return output;
162	}
163	
