45	        if ASCEND_IS_AIV {
46	            int wid = static_cast<int>(AscendC::GetBlockIdx());
47	            int wc = t_.launchBlocks;
48	            if (wc <= 0) wc = 1;
49	            for (int r = wid; r < t_.totalRows; r += wc) ComputeOneRow(r);
50	        }
51	    }
