65	template <typename T>
66	__aicore__ inline void UpsampleNearestKernel<T>::ComputeOneRow(int or_) {
67	    // Decompose row index into (n, oh, ow)
68	    int n = or_ / t_.outSpatial;
69	    int r = or_ - n * t_.outSpatial;
70	    int oh = r / t_.outW;
71	    int ow = r - oh * t_.outW;
72	
73	    // Compute source coordinates
74	    int srcH, srcW;
75	    int exact = t_.exactMode;
76	    if (exact) {
77	        // nearest-exact: src = round(dst * (in-1)/(out-1)), clamp to [0, in-1]
78	        if (t_.outH > 1) {
79	            float hc = static_cast<float>(oh) * static_cast<float>(t_.inH - 1) /
80	                       static_cast<float>(t_.outH - 1);
81	            srcH = static_cast<int>(hc + 0.5f);
82	        } else {
83	            srcH = 0;
84	        }
85	        if (t_.outW > 1) {
86	            float wc = static_cast<float>(ow) * static_cast<float>(t_.inW - 1) /
87	                       static_cast<float>(t_.outW - 1);
88	            srcW = static_cast<int>(wc + 0.5f);
89	        } else {
90	            srcW = 0;
91	        }
92	    } else {
93	        // nearest (non-exact): src = floor(dst * in/out), clamp to [0, in-1]
94	        float hs = static_cast<float>(oh) * t_.scaleH;
95	        float ws = static_cast<float>(ow) * t_.scaleW;
96	        srcH = static_cast<int>(hs);
97	        if (static_cast<float>(srcH) > hs) srcH--;
98	        srcW = static_cast<int>(ws);
99	        if (static_cast<float>(srcW) > ws) srcW--;
100	    }
101	    srcH = Clamp(srcH, 0, t_.inH - 1);
102	    srcW = Clamp(srcW, 0, t_.inW - 1);
103	
104	    // Compute source and destination offsets using paddedC as row stride
105	    int ib = n * t_.inSpatial;
106	    uint64_t srcRow = (static_cast<uint64_t>(ib) + srcH * t_.inW + srcW) * t_.paddedC;
107	    uint64_t dstRow = static_cast<uint64_t>(or_) * t_.paddedC;
108	
109	    // Copy channels in tiles
110	    for (int cs = 0; cs < t_.paddedC; cs += vL_) {
111	        int cl = vL_;
112	        if (cs + cl > t_.paddedC) cl = t_.paddedC - cs;
113	
114	        iq_.AllocTensor(iL_);
115	        AscendC::DataCopy(iL_, xG_[srcRow + cs], cl);
116	        iq_.EnQue(iL_);
117	        iq_.DeQue(iL_);
118	
119	        oq_.AllocTensor(oL_);
120	        AscendC::DataCopy(oL_, iL_, cl);
121	        oq_.EnQue(oL_);
122	        oq_.DeQue(oL_);
123	        AscendC::DataCopy(yG_[dstRow + cs], oL_, cl);
124	
125	        oq_.FreeTensor(oL_);
126	        iq_.FreeTensor(iL_);
127	    }
128	}
