#pragma once
#include "kernel_operator.h"

#pragma pack(push, 4)
struct UpsampleNearestExact3dTiling {
    int32_t N;
    int32_t C;
    int32_t paddedC;
    int32_t inD, inH, inW;
    int32_t outD, outH, outW;
    int32_t inSpatial;
    int32_t outSpatial;
    float scaleD;
    float scaleH;
    float scaleW;
    int32_t blockC;
    int32_t totalRows;
    int32_t launchBlocks;
};
#pragma pack(pop)

template <typename T> __aicore__ inline void CopyTiling(T* d, GM_ADDR s) {
    auto* dp = reinterpret_cast<int32_t*>(d);
    auto* sp = reinterpret_cast<__gm__ int32_t*>(s);
    for (size_t i = 0; i < sizeof(UpsampleNearestExact3dTiling) / 4; ++i) dp[i] = sp[i];
}

static __aicore__ inline int Clamp(int v, int lo, int hi) {
    return v < lo ? lo : (v > hi ? hi : v);
}

template <typename T>
class UpsampleNearestExact3dKernel {
public:
    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR g, AscendC::TPipe* p) {
        CopyTiling(&t_, g);
        xG_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(x),
                            static_cast<uint64_t>(t_.N) * t_.inSpatial * t_.paddedC);
        yG_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(y),
                            static_cast<uint64_t>(t_.N) * t_.outSpatial * t_.paddedC);
        if ASCEND_IS_AIV {
            pipe_ = p;
            vL_ = t_.blockC;
            uint32_t rawSz = static_cast<uint32_t>(vL_ * sizeof(T));
            uint32_t tSz = rawSz < 32 ? 32 : rawSz;
            pipe_->InitBuffer(iq_, 1, tSz);
            pipe_->InitBuffer(oq_, 1, tSz);
        }
    }

    __aicore__ inline void Process() {
        if ASCEND_IS_AIV {
            int wid = static_cast<int>(AscendC::GetBlockIdx());
            int wc = t_.launchBlocks;
            if (wc <= 0) wc = 1;
            for (int r = wid; r < t_.totalRows; r += wc) ComputeOneRow(r);
        }
    }

private:
    __aicore__ inline void ComputeOneRow(int or_);

    UpsampleNearestExact3dTiling t_;
    AscendC::GlobalTensor<T> xG_, yG_;
    AscendC::TPipe* pipe_;
    int vL_;
    AscendC::LocalTensor<T> iL_, oL_;
    AscendC::TQue<AscendC::TPosition::VECIN, 0> iq_;
    AscendC::TQue<AscendC::TPosition::VECOUT, 0> oq_;
};

template <typename T>
__aicore__ inline void UpsampleNearestExact3dKernel<T>::ComputeOneRow(int or_) {
    int n = or_ / t_.outSpatial;
    int r = or_ - n * t_.outSpatial;
    int od = r / (t_.outH * t_.outW);
    int r2 = r - od * (t_.outH * t_.outW);
    int oh = r2 / t_.outW;
    int ow = r2 - oh * t_.outW;

    // nearest-exact: src = floor((dst + 0.5) * scale), clamp to [0, inDim-1]
    float ds = (static_cast<float>(od) + 0.5f) * t_.scaleD;
    int srcD = static_cast<int>(ds);
    if (static_cast<float>(srcD) > ds) srcD--;
    srcD = Clamp(srcD, 0, t_.inD - 1);

    float hs = (static_cast<float>(oh) + 0.5f) * t_.scaleH;
    int srcH = static_cast<int>(hs);
    if (static_cast<float>(srcH) > hs) srcH--;
    srcH = Clamp(srcH, 0, t_.inH - 1);

    float ws = (static_cast<float>(ow) + 0.5f) * t_.scaleW;
    int srcW = static_cast<int>(ws);
    if (static_cast<float>(srcW) > ws) srcW--;
    srcW = Clamp(srcW, 0, t_.inW - 1);

    uint64_t srcRow = (static_cast<uint64_t>(n) * t_.inSpatial +
                       static_cast<uint64_t>(srcD) * t_.inH * t_.inW +
                       static_cast<uint64_t>(srcH) * t_.inW +
                       srcW) * t_.paddedC;
    uint64_t dstRow = static_cast<uint64_t>(or_) * t_.paddedC;

    for (int cs = 0; cs < t_.paddedC; cs += vL_) {
        int cl = vL_;
        if (cs + cl > t_.paddedC) cl = t_.paddedC - cs;

        iq_.AllocTensor(iL_);
        AscendC::DataCopy(iL_, xG_[srcRow + cs], cl);
        iq_.EnQue(iL_);
        iq_.DeQue(iL_);

        oq_.AllocTensor(oL_);
        AscendC::DataCopy(oL_, iL_, cl);
        oq_.EnQue(oL_);
        oq_.DeQue(oL_);
        AscendC::DataCopy(yG_[dstRow + cs], oL_, cl);

        oq_.FreeTensor(oL_);
        iq_.FreeTensor(iL_);
    }
}
