    int ow = r2 - oh * t_.outW;

    // nearest-exact: src = floor((dst + 0.5) * scale), clamp to [0, inDim-1]
    float ds = (static_cast<float>(od) + 0.5f) * t_.scaleD;
    int srcD = static_cast<int>(ds);
    if (static_cast<float>(srcD) > ds) srcD--;
    srcD = Clamp(srcD, 0, t_.inD - 1);

    float hs = (static_cast<float>(oh) + 0.5f) * t_.scaleH;
    int srcH = static_cast<int>(hs);
    if (static_cast<float>(srcH) > hs) srcH--;
    srcH = Clamp(srcH, 0, t_.inH - 1);

    float ws = (static_cast<float>(ow) + 0.5f) * t_.scaleW;
    int srcW = static_cast<int>(ws);
    if (static_cast<float>(srcW) > ws) srcW--;
    srcW = Clamp(srcW, 0, t_.inW - 1);

    uint64_t srcRow = (static_cast<uint64_t>(n) * t_.inSpatial +
                       static_cast<uint64_t>(srcD) * t_.inH * t_.inW +
                       static_cast<uint64_t>(srcH) * t_.inW +
                       srcW) * t_.paddedC;
    uint64_t dstRow = static_cast<uint64_t>(or_) * t_.paddedC;

    for (int cs = 0; cs < t_.paddedC; cs += vL_) {
        int cl = vL_;
        if (cs + cl > t_.paddedC) cl = t_.paddedC - cs;

        // GM → UB: DataCopyPad
        iq_.AllocTensor(iL_);
        AscendC::DataCopyExtParams copyInParams{1, static_cast<uint32_t>(cl * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPadExtParams<T> padParams{false, 0, 0, 0};
        AscendC::DataCopyPad(iL_, xG_[srcRow + cs], copyInParams, padParams);
        iq_.EnQue(iL_);
        iq_.DeQue(iL_);

        // UB → UB copy (pass-through)
        oq_.AllocTensor(oL_);
        AscendC::DataCopy(oL_, iL_, cl);
        oq_.EnQue(oL_);
        oq_.DeQue(oL_);

        // UB → GM: DataCopyPad
        AscendC::DataCopyExtParams copyOutParams{1, static_cast<uint32_t>(cl * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPad(yG_[dstRow + cs], oL_, copyOutParams);

        oq_.FreeTensor(oL_);
        iq_.FreeTensor(iL_);
    }
}
