#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

// Auto-generated by cmake
#include "aclrtlaunch_upsample_nearest_exact_3d_float.h"
#include "aclrtlaunch_upsample_nearest_exact_3d_half.h"
#include "aclrtlaunch_upsample_nearest_exact_3d_bf16.h"

#pragma pack(push, 4)
struct UpsampleNearestExact3dTiling {
    int32_t N;
    int32_t C;
    int32_t paddedC;
    int32_t inD, inH, inW;
    int32_t outD, outH, outW;
    int32_t inSpatial;
    int32_t outSpatial;
    float scaleD;
    float scaleH;
    float scaleW;
    int32_t blockC;
    int32_t totalRows;
    int32_t launchBlocks;
};
#pragma pack(pop)

namespace ascend_kernel {

at::Tensor upsample_nearest_exact_3d(
    const at::Tensor &input,
    at::IntArrayRef output_size,
    double scale_d,
    double scale_h,
    double scale_w)
{
    // Input validation
    TORCH_CHECK(input.ndimension() == 5,
                "upsample_nearest_exact_3d: expected 5D input (N,C,D,H,W), got ", input.ndimension());
    TORCH_CHECK(output_size.size() == 3,
                "upsample_nearest_exact_3d: output_size must have 3 elements, got ", output_size.size());

    int64_t nBatch = input.size(0);
    int64_t cDim = input.size(1);
    int64_t inD = input.size(2);
    int64_t inH = input.size(3);
    int64_t inW = input.size(4);
    int64_t outD = output_size[0];
    int64_t outH = output_size[1];
    int64_t outW = output_size[2];

    TORCH_CHECK(inD > 0 && inH > 0 && inW > 0,
                "upsample_nearest_exact_3d: input spatial dims must be > 0");
    TORCH_CHECK(outD > 0 && outH > 0 && outW > 0,
                "upsample_nearest_exact_3d: output spatial dims must be > 0");

    // Compute scale factors
    float scaleD = (scale_d <= 0.0) ? static_cast<float>(inD) / static_cast<float>(outD)
                                    : static_cast<float>(scale_d);
    float scaleH = (scale_h <= 0.0) ? static_cast<float>(inH) / static_cast<float>(outH)
                                    : static_cast<float>(scale_h);
    float scaleW = (scale_w <= 0.0) ? static_cast<float>(inW) / static_cast<float>(outW)
                                    : static_cast<float>(scale_w);

    // Channel tile size with vector alignment (32 bytes)
    int64_t elemSize = static_cast<int64_t>(input.element_size());
    int64_t vecWidth = 32 / elemSize;  // 8 for f32, 16 for f16/bf16
    int64_t paddedC = ((cDim + vecWidth - 1) / vecWidth) * vecWidth;

    int64_t inSpatial = inD * inH * inW;
    int64_t outSpatial = outD * outH * outW;
    int64_t totalRows = nBatch * outSpatial;
    int64_t inRows = nBatch * inSpatial;

    // Convert NCDHW → NDHWC layout and flatten
    auto inputNdhwc = input.permute({0, 2, 3, 4, 1}).contiguous();
    auto xFlat = inputNdhwc.reshape({inRows, cDim}).contiguous();

    // Pad C to vector width
    auto xPadded = at::zeros({inRows, paddedC}, input.options());
    xPadded.narrow(1, 0, cDim).copy_(xFlat);

    // Output: allocate padded (outRows, paddedC), zero-init
    auto yPadded = at::zeros({outRows, paddedC}, input.options());

    // Build tiling struct on CPU
    auto tilingCpu = at::empty({static_cast<int64_t>(sizeof(UpsampleNearestExact3dTiling))},
                                at::device(at::kCPU).dtype(at::kByte));
    auto *tilingPtr = reinterpret_cast<UpsampleNearestExact3dTiling *>(tilingCpu.data_ptr());
    tilingPtr->N = static_cast<int32_t>(nBatch);
    tilingPtr->C = static_cast<int32_t>(cDim);
    tilingPtr->paddedC = static_cast<int32_t>(paddedC);
    tilingPtr->inD = static_cast<int32_t>(inD);
    tilingPtr->inH = static_cast<int32_t>(inH);
    tilingPtr->inW = static_cast<int32_t>(inW);
    tilingPtr->outD = static_cast<int32_t>(outD);
    tilingPtr->outH = static_cast<int32_t>(outH);
    tilingPtr->outW = static_cast<int32_t>(outW);
    tilingPtr->inSpatial = static_cast<int32_t>(inSpatial);
    tilingPtr->outSpatial = static_cast<int32_t>(outSpatial);
    tilingPtr->scaleD = scaleD;
    tilingPtr->scaleH = scaleH;
    tilingPtr->scaleW = scaleW;
    tilingPtr->totalRows = static_cast<int32_t>(totalRows);

    // Set blockC (channel tile size for UB)
    int64_t blockC;
    if (paddedC <= 256) {
        blockC = paddedC;
    } else {
        blockC = 128;
    }
    tilingPtr->blockC = static_cast<int32_t>(blockC);

    // Copy tiling to device
    auto tilingNpu = tilingCpu.to(at::kPrivateUse1);

    // Get core count and UB size
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    // Validate UB budget: 2 io bufs (input + output) of blockC elements
    uint64_t requiredUB = static_cast<uint64_t>(blockC) * static_cast<uint64_t>(elemSize) * 2ULL;
    while (blockC > vecWidth && requiredUB > ubSize) {
        blockC = (blockC / 2 / vecWidth) * vecWidth;
        if (blockC < vecWidth) blockC = vecWidth;
        tilingPtr->blockC = static_cast<int32_t>(blockC);
        requiredUB = static_cast<uint64_t>(blockC) * static_cast<uint64_t>(elemSize) * 2ULL;
        tilingNpu = tilingCpu.to(at::kPrivateUse1);
    }

    // Set launch blocks
    int64_t blockDim = static_cast<int64_t>(coreNum);
    tilingPtr->launchBlocks = static_cast<int32_t>(blockDim);
    tilingNpu = tilingCpu.to(at::kPrivateUse1);

    // Launch kernel — all args must be lvalues
    if (input.scalar_type() == at::kFloat) {
        EXEC_KERNEL_CMD(upsample_nearest_exact_3d_float, blockDim,
                        xPadded, yPadded, tilingNpu);
    } else if (input.scalar_type() == at::kHalf) {
        EXEC_KERNEL_CMD(upsample_nearest_exact_3d_half, blockDim,
                        xPadded, yPadded, tilingNpu);
    } else if (input.scalar_type() == at::kBFloat16) {
        EXEC_KERNEL_CMD(upsample_nearest_exact_3d_bf16, blockDim,
                        xPadded, yPadded, tilingNpu);
    } else {
        TORCH_CHECK(false, "upsample_nearest_exact_3d: unsupported dtype ", input.scalar_type());
    }

    // Strip padding and convert back to NCDHW layout
    auto yFlat = yPadded.narrow(1, 0, cDim).contiguous();
    auto yNdhwc = yFlat.reshape({nBatch, outD, outH, outW, cDim});
    auto output = yNdhwc.permute({0, 4, 1, 2, 3}).contiguous();
    return output;
}

}  // namespace ascend_kernel
